class Solution {
public:
    long long findKthSmallest(vector<int>& coins, int k) {
        int n = coins.size();
        int minCoin = *min_element(coins.begin(), coins.end());
        long long hi = (long long)k * minCoin;

        auto gcdll = [](long long a, long long b) -> long long {
            while (b) { long long t = a % b; a = b; b = t; }
            return a;
        };

        auto count = [&](long long x) -> long long {
            long long res = 0;
            int total = 1 << n;
            for (int mask = 1; mask < total; mask++) {
                long long l = 1;
                int bits = 0;
                bool skip = false;
                for (int i = 0; i < n; i++) {
                    if (mask & (1 << i)) {
                        bits++;
                        long long c = coins[i];
                        long long g = gcdll(l, c);
                        if (l / g > x / c) { skip = true; break; }
                        l = l / g * c;
                    }
                }
                if (skip) continue;
                long long cnt = x / l;
                if (bits & 1) res += cnt;
                else res -= cnt;
            }
            return res;
        };

        long long lo = 1;
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (count(mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
